 settingsView(){return `<section class="view"><div class="section-head"><div><div class="eyebrow">Device preferences</div><h1>Settings</h1></div></div><div class="split"><aside class="settings-nav"><button class="btn primary" data-settab="appearance">Appearance</button><button class="btn ghost" data-settab="storage">Storage & backup</button><button class="btn ghost" data-settab="shortcuts">Keyboard shortcuts</button><button class="btn ghost" data-settab="privacy">Privacy & recovery</button></aside><div id="set-pane" class="settings-pane">${this.appearance()}</div></div></section>`}
 appearance(){return `<article class="card"><div class="card-head"><div><h2>Appearance</h2><p class="muted" style="font-size:12px">Adjust workspace without affecting your files.</p></div></div><div class="setting"><div class="setting-text"><b>Interface density</b><span>Changes spacing and text size throughout workspace.</span></div><select id="density" class="btn"><option value="compact">Compact</option><option value="comfortable">Comfortable</option><option value="large">Large</option></select></div><div class="setting"><div class="setting-text"><b>High contrast</b><span>Strengthens text and border contrast.</span></div><input id="contrast" class="switch" type="checkbox" ${this.settings.highContrast?'checked':''}></div><div class="setting"><div class="setting-text"><b>Spellcheck in editors</b><span>Uses browser spellcheck where it is available.</span></div><input id="spell" class="switch" type="checkbox" ${this.settings.spellcheck?'checked':''}></div><div class="setting"><div class="setting-text"><b>Default Writer export</b><span>Used by quick document export.</span></div><select id="default-format" class="btn"><option value="html">HTML</option><option value="markdown">Markdown</option><option value="text">Plain text</option></select></div></article>`}
 storage(){return `<article class="card"><div class="card-head"><div><h2>Storage & backup</h2><p class="muted" style="font-size:12px">Everything is stored in IndexedDB on this device.</p></div><span class="chip lime">offline local</span></div><div class="stats"><div class="stat"><div class="stat-value">${this.files.filter(f=>f.status==='active').length}</div><div class="stat-label">active files</div></div><div class="stat"><div class="stat-value">${this.files.filter(f=>f.status==='trash').length}</div><div class="stat-label">in trash</div></div><div class="stat"><div id="used" class="stat-value">…</div><div class="stat-label">estimated usage</div></div></div><div class="storage-bar"><i id="bar" style="width:0"></i></div><p id="storage-text" class="subtle">Checking browser storage…</p><div class="setting"><div class="setting-text"><b>Full local backup</b><span>Downloads JSON with files, revisions, settings, calendar, tasks, and responses.</span></div><button class="btn primary" id="backup">Export backup</button></div><div class="setting"><div class="setting-text"><b>Restore backup</b><span>Validate an archive, then merge or replace local workspace data.</span></div><button class="btn" id="restore">Restore…</button></div><div class="setting"><div class="setting-text"><b>Empty trash</b><span>Permanently removes trashed files and saved revisions.</span></div><button class="btn danger" id="empty-trash">Empty trash</button></div></article>`}
 privacy(){return `<article class="card"><div class="card-head"><h2>Privacy & recovery</h2></div><div class="setting"><div class="setting-text"><b>Autosave</b><span>Saves editor changes after a short pause and makes local snapshots.</span></div><input id="autosave" class="switch" type="checkbox" ${this.settings.autosave?'checked':''}></div><div class="setting"><div class="setting-text"><b>Clear all local workspace data</b><span>Deletes local files, revisions, settings, events, tasks, and responses. Export a backup first.</span></div><button class="btn danger" id="reset">Reset local data</button></div><p class="subtle">workspace has no account, telemetry, remote sync, or background upload.</p></article>`}
 short(){return `<article class="card"><div class="card-head"><h2>Keyboard shortcuts</h2></div><div class="shortcut-list"><kbd>Ctrl K</kbd><span>Search and commands</span><kbd>Ctrl N</kbd><span>Create a new file</span><kbd>Ctrl S</kbd><span>Save active file now</span><kbd>Ctrl Z</kbd><span>Undo in editor</span><kbd>Ctrl Shift Z</kbd><span>Redo in editor</span><kbd>Esc</kbd><span>Close dialogs and menus</span></div></article>`}
 bindSettings(){$$('[data-settab]').forEach(b=>b.onclick=()=>{const t=(b as HTMLElement).dataset.settab!;$$('[data-settab]').forEach(x=>{x.classList.remove('primary');x.classList.add('ghost')});b.classList.add('primary');b.classList.remove('ghost');$('#set-pane').innerHTML=t==='appearance'?this.appearance():t==='storage'?this.storage():t==='shortcuts'?this.short():this.privacy();this.bindSetPane(t)});this.bindSetPane('appearance')}
 async set(key:string,value:any){this.settings[key]=value;this.apply();await this.db.put('settings',{key,value})}
 bindSetPane(tab:string){if(tab==='appearance'){const d=$('#density')as HTMLSelectElement;d.value=this.settings.density;d.onchange=()=>this.set('density',d.value);const c=$('#contrast')as HTMLInputElement;c.onchange=()=>this.set('highContrast',c.checked);const s=$('#spell')as HTMLInputElement;s.onchange=()=>this.set('spellcheck',s.checked);const f=$('#default-format')as HTMLSelectElement;f.value=this.settings.defaultFormat;f.onchange=()=>this.set('defaultFormat',f.value)}if(tab==='storage'){this.estimate();$('#backup').onclick=()=>this.backup();$('#restore').onclick=()=>this.restorePicker();$('#empty-trash').onclick=()=>this.emptyTrash()}if(tab==='privacy'){const a=$('#autosave')as HTMLInputElement;a.onchange=()=>this.set('autosave',a.checked);$('#reset').onclick=()=>this.reset()}}
 async estimate(){try{const e=await navigator.storage.estimate(),u=e.usage||0,q=e.quota||0,bytes=(x:number)=>x<1024?x+' B':x<1048576?(x/1024).toFixed(1)+' KB':(x/1048576).toFixed(1)+' MB';$('#used').textContent=bytes(u);$('#storage-text').textContent=q?`${bytes(u)} used of roughly ${bytes(q)} available in this browser.`:`${bytes(u)} used in this browser.`;$('#bar').style.width=q?Math.min(100,u/q*100)+'%':'0'}catch{$('#storage-text').textContent='Storage estimates are unavailable.'}}
 editor(f:FileItem){return `<div class="editor-shell"><header class="editor-titlebar"><button class="icon-btn back-btn" id="back" aria-label="Back">←</button><div class="tabs">${this.open.map(id=>this.files.find(x=>x.id===id)).filter(Boolean).map((x:any)=>`<button class="tab ${x.id===f.id?'active':''}" data-tab="${x.id}">${this.dot(x)}<span class="tab-text">${esc(x.name)}</span><span class="tab-close" data-close="${x.id}">×</span></button>`).join('')}</div><div class="editor-actions"><span id="status" class="save-status">Saved locally</span><button class="btn" id="export">Export</button><button class="btn" id="more">⋯</button></div></header>${this.editorBody(f)}</div><div id="toast-stack" class="toast-stack" aria-live="polite"></div>`}
